import React, { useCallback, useEffect, useRef, useState } from 'react';
import { HUSH_EVENT } from './musicHush';

// The owner's own track (generated by the owner, no one else's rights) plays quietly
// in the background. Browsers only let sound start after the visitor's first tap
// or key press, so it starts then, unless the visitor switched it off before
// (remembered). It steps aside while something else with sound plays: a video
// on the site, a YouTube video, or an embedded player the visitor clicked into.

const SRC = '/audio/concrete-alibi.mp3';
const DEFAULT_VOLUME = 0.3;

const read = (key) => {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
};
const save = (key, value) => {
  try {
    localStorage.setItem(key, value);
  } catch {
    /* private mode: the choice lasts for this visit */
  }
};
const savedVolume = () => {
  const v = Number(read('musicVolume') ?? DEFAULT_VOLUME);
  return Number.isFinite(v) && v >= 0 && v <= 1 ? v : DEFAULT_VOLUME;
};

const BackgroundMusic = () => {
  const audioRef = useRef(null);
  // An iPhone ignores <audio>.volume, so the volume goes through Web Audio where it can.
  const gainRef = useRef(null);
  const [on, setOn] = useState(() => read('music') !== 'off');
  const [started, setStarted] = useState(false);
  const [volume, setVolume] = useState(savedVolume);
  const volumeRef = useRef(volume);
  const [mediaPlaying, setMediaPlaying] = useState(false);
  const [youTubePlaying, setYouTubePlaying] = useState(false);
  const [hidden, setHidden] = useState(() => document.visibilityState === 'hidden');
  const hushed = mediaPlaying || youTubePlaying;

  const play = useCallback(() => {
    const audio = audioRef.current;
    if (gainRef.current === null) {
      gainRef.current = false;
      const Context = window.AudioContext || window.webkitAudioContext;
      if (Context) {
        try {
          // Otherwise an iPhone on silent mutes Web Audio.
          if (navigator.audioSession) navigator.audioSession.type = 'playback';
          const context = new Context();
          const gain = context.createGain();
          gain.gain.value = volumeRef.current;
          audio.volume = 1;
          context.createMediaElementSource(audio).connect(gain).connect(context.destination);
          gainRef.current = gain;
        } catch {
          /* plain <audio> volume */
        }
      }
    }
    if (gainRef.current) gainRef.current.context.resume().catch(() => {});
    return Promise.resolve(audio.play()).then(() => setStarted(true));
  }, []);

  // The first tap or key anywhere (but on these controls) starts it.
  useEffect(() => {
    if (!on || started) return undefined;
    const start = (event) => {
      if (event.target instanceof Element && event.target.closest('.music-controls')) return;
      play().catch(() => {});
    };
    const events = ['pointerup', 'touchend', 'keydown'];
    events.forEach((type) => window.addEventListener(type, start, true));
    return () => events.forEach((type) => window.removeEventListener(type, start, true));
  }, [on, started, play]);

  const shouldPlay = on && started && !hushed && !hidden;
  useEffect(() => {
    if (shouldPlay) play().catch(() => {});
    else audioRef.current.pause();
  }, [shouldPlay, play]);

  useEffect(() => {
    volumeRef.current = volume;
    if (gainRef.current) gainRef.current.gain.value = volume;
    else audioRef.current.volume = volume;
  }, [volume]);

  useEffect(() => {
    // Any other <video> or <audio> with sound.
    const others = new Set();
    const onPlay = (event) => {
      if (event.target === audioRef.current || event.target.muted) return;
      others.add(event.target);
      setMediaPlaying(true);
    };
    const onStop = (event) => {
      if (others.delete(event.target)) setMediaPlaying(others.size > 0);
    };
    const onHush = (event) => setYouTubePlaying(Boolean(event.detail));
    // A click into an embedded player (YouTube, Instagram) moves focus into its frame.
    const onBlur = () => {
      if (document.activeElement?.tagName === 'IFRAME') setOn(false);
    };
    const onVisibility = () => setHidden(document.visibilityState === 'hidden');
    document.addEventListener('play', onPlay, true);
    ['pause', 'ended', 'emptied'].forEach((type) => document.addEventListener(type, onStop, true));
    window.addEventListener(HUSH_EVENT, onHush);
    window.addEventListener('blur', onBlur);
    document.addEventListener('visibilitychange', onVisibility);
    return () => {
      document.removeEventListener('play', onPlay, true);
      ['pause', 'ended', 'emptied'].forEach((type) => document.removeEventListener(type, onStop, true));
      window.removeEventListener(HUSH_EVENT, onHush);
      window.removeEventListener('blur', onBlur);
      document.removeEventListener('visibilitychange', onVisibility);
    };
  }, []);

  const toggle = () => {
    const next = !on;
    setOn(next);
    save('music', next ? 'on' : 'off');
    // Started from the tap itself, which the browser requires the first time.
    if (next && !hushed) play().catch(() => {});
  };

  const changeVolume = (event) => {
    const next = Number(event.target.value);
    setVolume(next);
    save('musicVolume', String(next));
  };

  const playing = on && started && !hushed;

  return (
    <div className={`music-controls ${playing ? 'playing' : ''}`}>
      <audio ref={audioRef} src={SRC} loop preload="none" />
      <button
        type="button"
        className="music-toggle"
        onClick={toggle}
        aria-pressed={on}
        aria-label={on ? 'Turn music off' : 'Turn music on'}
      >
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M11 5 6 9H3v6h3l5 4V5z" />
          {on ? (
            <>
              <path d="M15.5 8.5a5 5 0 0 1 0 7" />
              <path d="M18.5 5.5a9 9 0 0 1 0 13" />
            </>
          ) : (
            <>
              <line x1="16" y1="9" x2="22" y2="15" />
              <line x1="22" y1="9" x2="16" y2="15" />
            </>
          )}
        </svg>
      </button>
      <input
        type="range"
        className="music-volume"
        min="0"
        max="1"
        step="0.05"
        value={volume}
        onChange={changeVolume}
        aria-label="Music volume"
        style={{ '--fill': `${volume * 100}%` }}
      />
    </div>
  );
};

export default BackgroundMusic;
